// Rama sin alerta: se registra el chequeo para trazabilidad
const c = $input.first().json;
return [{ json: { estado: 'normal', metricas: c.metricas, timestamp: c.timestamp } }];

// ============================================================
//  Evaluacion de umbrales - NutriAlianza S.A.
//  Poner FORZAR_ALERTA en true para pruebas de demostracion
// ============================================================
const FORZAR_ALERTA = false;

const cfg = $('Configuracion').first().json;

function leerMetrica(nodo) {
  try {
    const items = $(nodo).all();
    for (const it of items) {
      let r = it.json;
      if (Array.isArray(r)) r = r[0];
      if (r && r.data && r.data.result && r.data.result.length > 0) {
        return parseFloat(r.data.result[0].value[1]);
      }
    }
    return null;
  } catch (e) {
    return null;
  }
}

const cpu   = leerMetrica('Metrica CPU');
const ram   = leerMetrica('Metrica RAM');
const disco = leerMetrica('Metrica Disco');

const debug_cpu = JSON.stringify($('Metrica CPU').all()[0].json).slice(0, 300);

let errores5xx = 0;
let muestraLogs = [];
try {
  const loki = $('Logs Nginx').all()[0].json;
  for (const s of (loki.data.result || [])) {
    for (const par of s.values) {
      muestraLogs.push(par[1]);
      if (/" 5\d{2} /.test(par[1])) errores5xx++;
    }
  }
} catch (e) { muestraLogs = []; }
muestraLogs = muestraLogs.slice(0, 15);

const umbrales = { cpu: 85, ram: 90, disco: 85, errores5xx: 20 };

const alertas = [];
if (cpu   !== null && cpu   > umbrales.cpu)   alertas.push(`CPU al ${cpu.toFixed(1)}% (umbral ${umbrales.cpu}%)`);
if (ram   !== null && ram   > umbrales.ram)   alertas.push(`RAM al ${ram.toFixed(1)}% (umbral ${umbrales.ram}%)`);
if (disco !== null && disco > umbrales.disco) alertas.push(`Disco al ${disco.toFixed(1)}% (umbral ${umbrales.disco}%)`);
if (errores5xx > umbrales.errores5xx)         alertas.push(`${errores5xx} errores 5xx en 5 min (umbral ${umbrales.errores5xx})`);

if (FORZAR_ALERTA && alertas.length === 0) {
  alertas.push(`PRUEBA CONTROLADA - CPU ${cpu !== null ? cpu.toFixed(1) : 'n/d'}%, RAM ${ram !== null ? ram.toFixed(1) : 'n/d'}%`);
}

return [{
  json: {
    hay_alerta: alertas.length > 0,
    alertas: alertas,
    resumen_alertas: alertas.join(' | '),
    metricas: {
      cpu_pct:   cpu   !== null ? Number(cpu.toFixed(2))   : null,
      ram_pct:   ram   !== null ? Number(ram.toFixed(2))   : null,
      disco_pct: disco !== null ? Number(disco.toFixed(2)) : null,
      debug_cpu: debug_cpu,
      errores_5xx_5min: errores5xx
    },
    umbrales: umbrales,
    muestra_logs: muestraLogs,
    timestamp: new Date().toISOString(),
    telegram_token: cfg.telegram_token,
    telegram_chat_id: cfg.telegram_chat_id,
    groq_api_key: cfg.groq_api_key
  }
}];

