// ============================================================
// Formateo del mensaje de alerta para Telegram
// ============================================================

const ctx = $('Evaluar Umbrales').first().json;
const resp = $input.first().json;

function esc(t) {
  return String(t == null ? '' : t)
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;');
}

let ia;
try {
  let bruto = resp.choices[0].message.content;
  bruto = bruto.replace(/```json/gi, '').replace(/```/g, '').trim();
  ia = JSON.parse(bruto);
} catch (e) {
  ia = {
    severidad: 'media',
    componente_afectado: 'indeterminado',
    causa_probable: 'No fue posible interpretar la respuesta del modelo.',
    impacto_operativo: 'Requiere revision manual.',
    accion_recomendada: 'Revisar Grafana y los logs del servidor.',
    comando_diagnostico: 'docker compose ps'
  };
}

const iconos = {
  baja: '\u{1F7E2}',
  media: '\u{1F7E1}',
  alta: '\u{1F7E0}',
  critica: '\u{1F534}'
};
const icono = iconos[(ia.severidad || '').toLowerCase()] || '\u26A0\uFE0F';

const m = ctx.metricas;

const mensaje =
  `${icono} <b>ALERTA - NutriAlianza S.A.</b>\n` +
  `<i>Severidad: ${esc((ia.severidad || 'n/d')).toUpperCase()}</i>\n\n` +
  `<b>Condicion detectada</b>\n${esc(ctx.resumen_alertas)}\n\n` +
  `<b>Telemetria</b>\n` +
  `CPU: ${m.cpu_pct ?? 'n/d'}%  |  RAM: ${m.ram_pct ?? 'n/d'}%\n` +
  `Disco: ${m.disco_pct ?? 'n/d'}%  |  Errores 5xx: ${m.errores_5xx_5min}\n\n` +
  `<b>Analisis del motor de IA</b>\n` +
  `Componente: ${esc(ia.componente_afectado)}\n` +
  `Causa probable: ${esc(ia.causa_probable)}\n` +
  `Impacto: ${esc(ia.impacto_operativo)}\n\n` +
  `<b>Accion recomendada</b>\n${esc(ia.accion_recomendada)}\n\n` +
  `<code>${esc(ia.comando_diagnostico)}</code>\n\n` +
  `<i>${esc(ctx.timestamp)}  |  Servidor nutrialianza-srv01</i>`;

return [{
  json: {
    mensaje: mensaje,
    analisis_ia: ia,
    contexto: ctx.metricas,
    telegram_token: ctx.telegram_token,
    telegram_chat_id: ctx.telegram_chat_id
  }
}];
